import{c as e,Q as t,j as i,m as s}from"./chunks/framework.CWBTDBPu.js";const u=JSON.parse('{"title":"YuChat 常见问题","description":"","frontmatter":{"title":"YuChat 常见问题"},"headers":[],"relativePath":"plugins/items/yu-chat/faq.md","filePath":"plugins/items/yu-chat/faq.md"}'),l={name:"plugins/items/yu-chat/faq.md"};function d(h,a,o,r,n,c){return t(),i("div",null,[...a[0]||(a[0]=[s(`<h1 id="yuchat-常见问题" tabindex="-1">YuChat 常见问题 <a class="header-anchor" href="#yuchat-常见问题" aria-label="Permalink to &quot;YuChat 常见问题&quot;">​</a></h1><h2 id="yuchat-支持哪些服务端" tabindex="-1">YuChat 支持哪些服务端？ <a class="header-anchor" href="#yuchat-支持哪些服务端" aria-label="Permalink to &quot;YuChat 支持哪些服务端？&quot;">​</a></h2><p>目标适配范围与 YuTeleport 一致：Minecraft <code>1.8.x-1.26.x</code>，Spigot、Paper、Paper 衍生端，以及 Mohist、Arclight、Youer 等 Bukkit API 混合端。混合端聊天、TAB、实体头顶名和第三方插件改写链路更复杂，上线前建议重点测试聊天格式、TAB 插件、群组互联、死亡消息和 MySQL 同步。</p><h2 id="玩家输入颜色没有效果" tabindex="-1">玩家输入颜色没有效果？ <a class="header-anchor" href="#玩家输入颜色没有效果" aria-label="Permalink to &quot;玩家输入颜色没有效果？&quot;">​</a></h2><p>先检查权限：</p><table tabindex="0"><thead><tr><th>颜色能力</th><th>权限</th></tr></thead><tbody><tr><td><code>&amp;</code> / <code>§</code> legacy 颜色</td><td><code>yuchat.chat.color</code></td></tr><tr><td>MiniMessage 标签</td><td><code>yuchat.chat.minimessage</code></td></tr><tr><td>Hex 颜色</td><td><code>yuchat.chat.hex</code></td></tr><tr><td>聊天内容 PAPI</td><td><code>yuchat.chat.placeholder</code></td></tr></tbody></table><p>低版本客户端会自动降级颜色表现，1.16+ 才能原生显示 Hex 与渐变。</p><h2 id="tab-或头顶名没有显示-yuchat-内容" tabindex="-1">TAB 或头顶名没有显示 YuChat 内容？ <a class="header-anchor" href="#tab-或头顶名没有显示-yuchat-内容" aria-label="Permalink to &quot;TAB 或头顶名没有显示 YuChat 内容？&quot;">​</a></h2><p>如果安装了 TAB、计分板或头顶名插件，它们可能覆盖 Bukkit 原生显示。推荐在这些插件中直接使用 YuChat 变量：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">customtabname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%yuchat_tab%&quot;</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">customtagname</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;%yuchat_prefix%%yuchat_title% %yuchat_nickname%%yuchat_suffix%&quot;</span></span></code></pre></div><p>同时确认 <code>placeholder.expansion.enabled: true</code>，并且 PlaceholderAPI 已安装。</p><h2 id="luckperms-前缀或后缀没有读取到" tabindex="-1">LuckPerms 前缀或后缀没有读取到？ <a class="header-anchor" href="#luckperms-前缀或后缀没有读取到" aria-label="Permalink to &quot;LuckPerms 前缀或后缀没有读取到？&quot;">​</a></h2><p>按顺序检查：</p><ol><li>LuckPerms 是否已安装并正常启用。</li><li>玩家所在组是否真的设置了 prefix、suffix 或 meta。</li><li><code>prefix-suffix.enabled</code> 是否为 <code>true</code>。</li><li><code>prefix-suffix.prefix.parts</code> 与 <code>suffix.parts</code> 是否包含需要的片段。</li><li>若使用 PAPI 兜底，PlaceholderAPI 与 LuckPerms 扩展是否可用。</li></ol><p>排查时可临时在菜单、TAB 或聊天中展示 <code>%yuchat_prefix_raw%</code> 与 <code>%yuchat_suffix_raw%</code>。</p><h2 id="群组互联或聊天记录插件收不到消息" tabindex="-1">群组互联或聊天记录插件收不到消息？ <a class="header-anchor" href="#群组互联或聊天记录插件收不到消息" aria-label="Permalink to &quot;群组互联或聊天记录插件收不到消息？&quot;">​</a></h2><p>保持默认配置时，YuChat 会尽量保留 Bukkit 原始聊天事件。如果你开启了聊天内悬浮，YuChat 可能会取消原事件并使用 TextComponent 广播。</p><p>优先检查：</p><div class="language-yaml vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">chat-format</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  component-broadcast</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  hover</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    enabled</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">false</span></span></code></pre></div><p>需要悬浮时可以只开启 prefix、suffix、nickname 或 title，尽量避免开启 <code>hover.message</code>。</p><h2 id="首次启动下载依赖失败怎么办" tabindex="-1">首次启动下载依赖失败怎么办？ <a class="header-anchor" href="#首次启动下载依赖失败怎么办" aria-label="Permalink to &quot;首次启动下载依赖失败怎么办？&quot;">​</a></h2><p>YuChat 会从 Maven Central 下载 HikariCP、SQLite JDBC、MySQL JDBC、SLF4J 等依赖到 <code>plugins/YuChat/libs/</code>。如果服务器无法访问 Maven Central：</p><ol><li>在可联网环境下载对应 jar。</li><li>放入 <code>plugins/YuChat/libs/</code>。</li><li>保持文件名为 <code>artifact-version.jar</code>。</li><li>重启服务端。</li></ol><p>不建议关闭 <code>library.verify-checksum</code>，除非你确认依赖来源可靠且校验源不可访问。</p><h2 id="mysql-模式下数据不同步" tabindex="-1">MySQL 模式下数据不同步？ <a class="header-anchor" href="#mysql-模式下数据不同步" aria-label="Permalink to &quot;MySQL 模式下数据不同步？&quot;">​</a></h2><p>检查所有子服是否使用：</p><table tabindex="0"><thead><tr><th>项目</th><th>要求</th></tr></thead><tbody><tr><td>同一插件版本</td><td>避免表结构或字段差异。</td></tr><tr><td>同一数据库</td><td>host、port、database、username、password 一致。</td></tr><tr><td>同一表前缀</td><td><code>storage.table-prefix</code> 一致。</td></tr><tr><td>同一称呼/效果配置</td><td>避免某个子服没有对应 ID。</td></tr></tbody></table><p>修改昵称、称呼和显示开关后，玩家重新进服或触发显示同步通常会看到最新状态。</p><h2 id="经济扣费没有发生" tabindex="-1">经济扣费没有发生？ <a class="header-anchor" href="#经济扣费没有发生" aria-label="Permalink to &quot;经济扣费没有发生？&quot;">​</a></h2><p>确认 <code>economy</code> 或称呼 <code>payment</code> 节点中 <code>enabled: true</code>，并且 <code>mode</code> 不是 <code>none</code>。Vault 模式需要安装 Vault 和实际经济插件；PlayerPoints 模式需要安装 PlayerPoints。</p><h2 id="管理员-gui-创建的称呼在哪里" tabindex="-1">管理员 GUI 创建的称呼在哪里？ <a class="header-anchor" href="#管理员-gui-创建的称呼在哪里" aria-label="Permalink to &quot;管理员 GUI 创建的称呼在哪里？&quot;">​</a></h2><p>管理员 GUI 创建的称呼会保存到：</p><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>plugins/YuChat/custom_titles.yml</span></span></code></pre></div><p>内置称呼在 <code>titles.yml</code>。两个文件中的称呼 ID 不应重复。</p><h2 id="死亡消息里的击杀者不准确" tabindex="-1">死亡消息里的击杀者不准确？ <a class="header-anchor" href="#死亡消息里的击杀者不准确" aria-label="Permalink to &quot;死亡消息里的击杀者不准确？&quot;">​</a></h2><p>YuChat 会从最后一次伤害事件解析真实伤害来源，包括生物、弹射物、TNT 等。若其他插件深度改写死亡事件或伤害来源，建议在测试服复现并检查控制台是否有相关报错。</p><h2 id="修改配置后-gui-没变化" tabindex="-1">修改配置后 GUI 没变化？ <a class="header-anchor" href="#修改配置后-gui-没变化" aria-label="Permalink to &quot;修改配置后 GUI 没变化？&quot;">​</a></h2><p>执行 <code>/yc reload</code>。如果 <code>reload.gui.reopen-main-after-reload</code> 为 <code>true</code>，正在查看 YuChat GUI 的玩家会自动关闭旧界面并打开主界面；否则需要玩家手动重新打开。</p>`,38)])])}const k=e(l,[["render",d]]);export{u as __pageData,k as default};
